<?php require 'includes/functions.php';require_login();$q=trim($_GET['q']??'');$type=$_GET['type']??'';$where=["r.status<>'hidden'"];$args=[];if($q){$where[]='(r.title LIKE ? OR r.description LIKE ? OR r.location LIKE ? OR r.category LIKE ?)';for($i=0;$i<4;$i++)$args[]='%'.$q.'%';}if(in_array($type,['lost','found'])){$where[]='r.type=?';$args[]=$type;}$sql='SELECT r.*,u.name,(SELECT COUNT(*) FROM comments c WHERE c.report_id=r.id) comments FROM reports r JOIN users u ON u.id=r.user_id WHERE '.implode(' AND ',$where).' ORDER BY r.created_at DESC';$st=$pdo->prepare($sql);$st->execute($args);$reports=$st->fetchAll();$counts=$pdo->query("SELECT COUNT(*) total,SUM(type='lost' AND status='open') lost,SUM(type='found' AND status='open') found,SUM(status='resolved') resolved FROM reports WHERE status<>'hidden'")->fetch();$title='Comunidad';require 'includes/header.php';?>
<main class="dashboard"><div class="welcome"><div><h1>Hola, <?=e(explode(' ',user()['name'])[0])?></h1><p class="muted">Explora los reportes recientes de la comunidad.</p></div><a class="btn primary" href="<?=url('reports/create.php')?>">＋ Nuevo reporte</a></div>
<div class="stats"><div class="stat"><span class="muted">Publicaciones</span><b><?=intval($counts['total'])?></b></div><div class="stat"><span class="muted">Perdidos activos</span><b><?=intval($counts['lost'])?></b></div><div class="stat"><span class="muted">Encontrados activos</span><b><?=intval($counts['found'])?></b></div><div class="stat"><span class="muted">Casos resueltos</span><b><?=intval($counts['resolved'])?></b><small>Objetos recuperados o entregados</small></div></div>
<form class="toolbar"><input class="input" name="q" placeholder="Buscar por objeto, lugar, categoría..." value="<?=e($q)?>"><select name="type"><option value="">Todos los reportes</option><option value="lost" <?=$type==='lost'?'selected':''?>>Objetos perdidos</option><option value="found" <?=$type==='found'?'selected':''?>>Objetos encontrados</option></select><button class="btn primary">Buscar</button></form><div class="feed"><?php foreach($reports as $r):?><a class="post" href="<?=url('reports/view.php?id='.$r['id'])?>"><div class="post-img"><?php if($r['image'] && !$r['is_sensitive']):?><img src="<?=url('uploads/'.e($r['image']))?>"><?php else:?><div class="placeholder"><?=$r['is_sensitive']?'🪪':'🎒'?></div><?php endif;?></div><div class="post-body"><div class="post-meta"><span class="badge <?=e($r['type'])?>"><?=$r['type']==='lost'?'PERDIDO':'ENCONTRADO'?></span><?php if($r['status']==='resolved'):?><span class="badge resolved"><?=resolved_label($r)?></span><?php endif;?><span><?=timeago($r['created_at'])?></span></div><h3><?=e($r['title'])?></h3><p>📍 <?=e($r['location'])?> · <?=date('d/m/Y',strtotime($r['event_date']))?></p><div class="author"><span class="avatar"><?=e(mb_substr($r['name'],0,1))?></span><span><b><?=e($r['name'])?></b><br><span class="muted">💬 <?=$r['comments']?> comentarios</span></span></div></div></a><?php endforeach;?></div><?php if(!$reports):?><div class="empty">🔎<h3>No encontramos reportes</h3><p>Prueba otra búsqueda o crea una nueva publicación.</p></div><?php endif;?></main><?php require 'includes/footer.php';?>
